/**
 * Offline eval harness for Twyne's persona feedback / rubric judges.
 *
 * Reads each line in `evals/dataset.jsonl`, builds the same system + user
 * prompts the production actions build via `convex/agentPrompts`, then
 * calls the Not Organic gateway that `convex/agents.ts` already routes
 * through. Writes the model outputs to `evals/runs.json` in the shape
 * `ax experiments create --file` accepts.
 *
 * Usage:
 *   bun run eval
 *
 * Calls the Not Organic gateway; see evals/llm-client.ts.
 *
 * Read-only w.r.t. the repo otherwise: only writes `evals/runs.json`.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import {
  buildSystemPrompt,
  buildUserPrompt,
  toAgentPersona,
  type AgentPersona,
  type AgentRequest,
} from "../convex/agentPrompts";
import { PERSONAS } from "../src/utils/personas";
import { chatCompletion, DEFAULT_MODEL } from "./llm-client";

const HERE = dirname(fileURLToPath(import.meta.url));
const DATASET_PATH = resolve(HERE, "dataset.jsonl");
const RUNS_PATH = resolve(HERE, "runs.json");

interface DatasetRow {
  case_id: string;
  persona: string;
  instruction: string;
  draftText: string;
}

interface RunOutput {
  // Local stable key (the dataset's case_id). The Arize-assigned example_id is
  // resolved at upload time by joining on case_id (see evals/upload-experiment.ts).
  case_id: string;
  output: string;
}

function personaOrThrow(id: string): AgentPersona {
  const p = PERSONAS.find((x) => x.id === id);
  if (!p) {
    throw new Error(
      `Unknown persona id "${id}" — add it to src/utils/personas.ts`,
    );
  }
  return toAgentPersona(p);
}

function readDataset(): DatasetRow[] {
  const raw = readFileSync(DATASET_PATH, "utf8").trim();
  return raw
    .split(/\n+/)
    .filter(Boolean)
    .map((line, i) => {
      try {
        return JSON.parse(line) as DatasetRow;
      } catch (err) {
        throw new Error(`Bad JSONL line ${i + 1}: ${(err as Error).message}`);
      }
    });
}

async function main(): Promise<void> {
  const dataset = readDataset();
  console.log(`[twyne:eval] ${dataset.length} examples → ${DEFAULT_MODEL}`);
  const runs: RunOutput[] = [];
  let failures = 0;
  for (const row of dataset) {
    const persona = personaOrThrow(row.persona);
    const req: AgentRequest = {
      persona,
      brief: null,
      draftText: row.draftText,
      instruction: row.instruction as AgentRequest["instruction"],
    };
    const system = buildSystemPrompt(persona);
    const user = buildUserPrompt(req);
    try {
      const output = await chatCompletion({
        system,
        user,
        model: DEFAULT_MODEL,
        temperature: 0.4,
        signal: AbortSignal.timeout(60_000),
      });
      runs.push({ case_id: row.case_id, output });
      console.log(`  ✓ ${row.case_id} (${output.length} chars)`);
    } catch (err) {
      failures += 1;
      const message = (err as Error).message;
      runs.push({
        case_id: row.case_id,
        output: `[error] ${message}`,
      });
      console.error(`  ✗ ${row.case_id}: ${message}`);
    }
  }
  writeFileSync(RUNS_PATH, JSON.stringify(runs, null, 2));
  console.log(
    `[twyne:eval] wrote ${runs.length} runs (${failures} failed) to evals/runs.json`,
  );
  if (failures > 0) {
    process.exitCode = 1;
  }
}

main().catch((err) => {
  console.error("[twyne:eval] fatal:", err);
  process.exit(1);
});
/**
 * Account-metered Not Organic client shared by evals and prompt optimization.
 * Requires NOTORGANIC_ENABLED, assertion signing configuration, TWYNE_EVAL_DID,
 * and an explicit TWYNE_EVAL_MAX_COST_MICROUSD ceiling. See README.notorganic.md.
 */
import {
  issueNotOrganicAccessToken,
  notOrganicEnabled,
  notOrganicGenerationBudgetMicrousd,
  notOrganicGenerationRequestHeaders,
  notOrganicIssuer,
  notOrganicOpenAiRoute,
} from "../convex/lib/notorganic";

export const DEFAULT_MODEL = process.env.TWYNE_EVAL_MODEL ?? "balanced";
export const JUDGE_MODEL = process.env.JUDGE_MODEL ?? "reasoning";
const TEXT_ALIASES = ["fast", "balanced", "reasoning"] as const;
type TextAlias = (typeof TEXT_ALIASES)[number];

export interface ChatOptions {
  system: string;
  user: string;
  model: string;
  temperature: number;
  maxTokens?: number | null;
  signal: AbortSignal;
}

type Env = Readonly<Record<string, string | undefined>>;

export function evalConfiguration(env: Env = process.env) {
  if (!notOrganicEnabled(env))
    throw new Error("NOTORGANIC_ENABLED must be true for hosted evals");
  if (!env.NOTORGANIC_ASSERTION_PRIVATE_KEY)
    throw new Error(
      "NOTORGANIC_ASSERTION_PRIVATE_KEY is required for hosted evals",
    );
  const did = env.TWYNE_EVAL_DID?.trim();
  if (!did || !/^did:[a-z0-9]+:[^\s]+$/.test(did))
    throw new Error(
      "TWYNE_EVAL_DID must explicitly identify the account funding evals",
    );
  const maxCostMicrousd = notOrganicGenerationBudgetMicrousd(
    env.TWYNE_EVAL_MAX_COST_MICROUSD,
  );
  const issuer = notOrganicIssuer(env);
  const url = new URL(issuer);
  if (
    url.protocol !== "https:" ||
    url.username ||
    url.password ||
    url.search ||
    url.hash ||
    url.pathname !== "/"
  ) {
    throw new Error("NOTORGANIC_ISSUER must be an HTTPS origin");
  }
  return { did, maxCostMicrousd, issuer };
}

function textAlias(value: unknown): TextAlias {
  if (!TEXT_ALIASES.includes(value as TextAlias))
    throw new Error(
      "Eval model must be a Not Organic alias: fast, balanced, or reasoning",
    );
  return value as TextAlias;
}

function sleep(ms: number, signal: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    signal.throwIfAborted();
    const abort = () => {
      clearTimeout(timer);
      reject(signal.reason ?? new Error("aborted"));
    };
    const timer = setTimeout(() => {
      signal.removeEventListener("abort", abort);
      resolve();
    }, ms);
    signal.addEventListener("abort", abort, { once: true });
  });
}

/** Dependency injection is for offline contract tests; production uses fetch. */
export function createEvalClient(
  env: Env = process.env,
  fetchImpl: typeof fetch = fetch,
) {
  return async function completeChatBody(
    body: Record<string, unknown>,
    signal: AbortSignal,
  ): Promise<string> {
    signal.throwIfAborted();
    const config = evalConfiguration(env);
    const alias = textAlias(body.model);
    if (!Array.isArray(body.messages) || body.messages.length === 0)
      throw new Error("Chat messages are required");
    const feature = "offline-eval";
    const authenticatedFetch = ((
      input: RequestInfo | URL,
      init?: RequestInit,
    ) => fetchImpl(input, { ...init, signal })) as typeof fetch;
    const token = await issueNotOrganicAccessToken(
      {
        did: config.did,
        feature,
        capabilities: [`infer:${alias}`],
      },
      env,
      authenticatedFetch,
    );
    const route = notOrganicOpenAiRoute(
      token,
      alias,
      feature,
      config.issuer,
      authenticatedFetch,
      {
        maxCostMicrousd: config.maxCostMicrousd,
      },
    );
    // All retries of this logical generation retain the same metering identity.
    const headers = notOrganicGenerationRequestHeaders(route.headers);
    const requestHeaders = Object.fromEntries(
      Object.entries(headers).filter(
        (entry): entry is [string, string] => typeof entry[1] === "string",
      ),
    );
    const payload = JSON.stringify({
      ...body,
      model: route.model,
      stream: false,
    });
    for (let attempt = 0; ; attempt += 1) {
      try {
        const response = await route.fetch(
          `${route.baseURL}/chat/completions`,
          {
            method: "POST",
            headers: { ...requestHeaders, "content-type": "application/json" },
            body: payload,
            signal,
          },
        );
        if (!response.ok) {
          // Never print gateway bodies: they may contain request or credential details.
          await response.body?.cancel();
          throw Object.assign(
            new Error(`Not Organic chat failed (${response.status})`),
            { status: response.status },
          );
        }
        const json = (await response.json()) as {
          choices?: Array<{ message?: { content?: unknown } }>;
        };
        const content = json.choices?.[0]?.message?.content;
        if (typeof content !== "string")
          throw new Error("Not Organic response missing chat content");
        return content;
      } catch (error) {
        signal.throwIfAborted();
        const e = error as Error & { status?: number };
        const retryable =
          e instanceof TypeError ||
          e.name === "FetchError" ||
          e.name === "UndiciError" ||
          (typeof e.status === "number" &&
            (e.status === 408 || e.status === 429 || e.status >= 500));
        if (!retryable || attempt >= 2) throw error;
        await sleep([1_500, 4_000][attempt]!, signal);
      }
    }
  };
}

export async function chatCompletion(opts: ChatOptions): Promise<string> {
  return createEvalClient()(
    {
      model: opts.model,
      messages: [
        { role: "system", content: opts.system },
        { role: "user", content: opts.user },
      ],
      temperature: opts.temperature,
      ...(opts.maxTokens == null ? {} : { max_tokens: opts.maxTokens }),
    },
    opts.signal,
  );
}
/** Stdin/stdout transport for Python; no HTTP listener and no secrets in arguments. */
import { readFileSync } from "node:fs";
import { createEvalClient, evalConfiguration } from "./llm-client";

try {
  evalConfiguration();
  if (process.argv.includes("--check")) {
    console.log(JSON.stringify({ ok: true }));
  } else {
    const input: unknown = JSON.parse(readFileSync(0, "utf8"));
    if (!input || typeof input !== "object" || Array.isArray(input))
      throw new Error("Chat object required");
    const content = await createEvalClient()(
      input as Record<string, unknown>,
      AbortSignal.timeout(180_000),
    );
    console.log(JSON.stringify({ content }));
  }
} catch {
  // This process receives signing keys via environment. Do not relay raw errors.
  console.error(
    "Not Organic optimizer request failed; check configuration, account access, and gateway status.",
  );
  process.exitCode = 1;
}

