const RUNS_PATH = resolve(HERE, "runs.json");
const SCORES_PATH = resolve(HERE, "scores.json");

interface DatasetRow {
  case_id: string;
  persona: string;
  instruction: string;
  draftText: string;
}
interface RunOutput {
  case_id: string;
  output: string;
  /** Optional production `$ai_trace_id` when a sample was exported from PostHog. */
  trace_id?: string;
}
interface Verdict {
  label: string;
  score: number | null;
  explanation: string;
}
interface CaseScore {
  case_id: string;
  trace_id?: string;
  persona: string;
  faithfulness: Verdict;
  helpfulness: Verdict;
}

