import { convexTest } from "convex-test";
import { createServer } from "node:http";
import { expect, test } from "vitest";
import { api } from "./_generated/api";
import schema from "./schema";

const modules = import.meta.glob("./**/*.ts");

test("probe: judgeDraft runs in-process against a stub OpenAI server", async () => {
  const calls: unknown[] = [];
  const server = createServer((req, res) => {
    let body = "";
    req.on("data", (c) => (body += c));
    req.on("end", () => {
      calls.push({ url: req.url, body: JSON.parse(body || "{}") });
      res.setHeader("content-type", "application/json");
      res.end(JSON.stringify({
        id: "x", object: "chat.completion", created: 1, model: "stub",
        choices: [{ index: 0, finish_reason: "stop", message: { role: "assistant", content: '{"score": 7, "rationale": "The second paragraph names the tidal pools specifically."}' } }],
        usage: { prompt_tokens: 10, completion_tokens: 10, total_tokens: 20 },
      }));
    });
  });
  await new Promise<void>((r) => server.listen(0, "127.0.0.1", () => r()));
  const port = (server.address() as { port: number }).port;
  process.env.RIVET_ENDPOINT = `http://127.0.0.1:${port}`;
  process.env.RIVET_MODEL = "stub-model";
  delete process.env.NOTORGANIC_ENABLED;
  const t = convexTest(schema, modules);
  const writer = t.withIdentity({ tokenIdentifier: "test|probe", subject: "probe" });
  const draft = Array.from({ length: 60 }, (_, i) => `Sentence ${i} about tidal pools and the salt road we walked.`).join(" ");
  const result = await writer.action(api.agents.judgeDraft, {
    persona: { id: "editor", name: "The Editor", role: "line editor", systemPrompt: "You edit.", temperature: 0.2 } as never,
    brief: null as never,
    draftText: draft,
  } as never);
  console.log("RESULT", JSON.stringify(result), "CALLS", calls.length, JSON.stringify(calls[0]).slice(0, 300));
  server.close();
  expect(calls.length).toBeGreaterThan(0);
}, 60_000);
EOF
