import type { LanguageModel } from "ai";

/**
 * In-process model override for hosted AI.
 *
 * Deployed functions never set this. It exists for harnesses that load the
 * Convex modules into their own process — `convex-test` suites and the app
 * eval harness in `evals/app/` — so the production code path (prompt assembly,
 * tool loops, adaptive drafting, parsing, usage capture) runs unchanged while
 * the model behind it is a scripted mock or an eval-selected endpoint.
 *
 * `pickProvider` consults the resolver before Not Organic and the legacy
 * environment keys. Returning `null` falls through to the normal selection.
 */

export type HostedModelAlias = "fast" | "balanced" | "reasoning";

export interface HostedModelChoice {
  model: LanguageModel;
  label: "rivet" | "anthropic" | "openai" | "portkey";
  modelId: string;
}

export type HostedModelResolver = (request: {
  feature: string;
  alias: HostedModelAlias;
}) => HostedModelChoice | null;

let resolver: HostedModelResolver | null = null;

export function setHostedModelOverride(next: HostedModelResolver | null): void {
  resolver = next;
}

export function hostedModelOverride(): HostedModelResolver | null {
  return resolver;
}

