    try {
      return {
        kind: "synthesis",
        brief: JSON.parse(legacySynthMatch[1]) as ProjectInterviewAnswers,
        confidence: legacySynthMatch[2]
          ? (JSON.parse(legacySynthMatch[2]) as Partial<
