/** The judge's instructions for a closed label set. */
export function judgeSystemPrompt(labels: readonly string[]): string {
  return (
    `You are a strict evaluator. Read the rubric, then respond with a JSON object ` +
    `exactly: {"label": "<one of: ${labels.join(", ")}>", "explanation": "<one sentence>"}. ` +
    `No other text.`
  );
}

async function judge(
  prompt: string,
  valid: Record<string, number>,
  signal: AbortSignal,
): Promise<Verdict> {
  const raw = await chatCompletion({
    system: judgeSystemPrompt(Object.keys(valid)),
    user: prompt,
    model: JUDGE_MODEL,
    temperature: 0,
    signal,
  });
  return parseVerdict(raw, valid);
}

/** Read a label verdict, tolerating fences and prose around the JSON. */
export function parseVerdict(
  raw: string,
  valid: Record<string, number>,
): Verdict {
  const labels = Object.keys(valid);
  let label = "";
  let explanation = "";
  let txt = raw.trim();
  if (txt.startsWith("```")) {
    txt = txt
      .replace(/^```[a-z]*\n?/, "")
      .replace(/```$/, "")
      .trim();
  }
  try {
    const obj = JSON.parse(txt) as { label?: string; explanation?: string };
    label = String(obj.label ?? "")
      .trim()
      .toLowerCase();
    explanation = String(obj.explanation ?? "").trim();
  } catch {
    const low = raw.toLowerCase();
    label = labels.find((l) => low.includes(l)) ?? "?";
    explanation = raw.trim().slice(0, 200);
  }
  if (!(label in valid)) {
    label = labels.find((l) => label.includes(l)) ?? "?";
  }
  return { label, score: label in valid ? valid[label] : null, explanation };
}

function readDataset(): Map<string, DatasetRow> {
}

// Imported by evals/app for the shared rubric wording; only run as a script.
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((err) => {
    console.error("[twyne:judge] fatal:", err);
    process.exit(1);
  });
}

