    requestedScope?: string;
  }): Promise<{
    access_token: string;
    token_type: "DPoP";
    expires_in: 300;
    scope: string;
  }> {
    const assertion = await this.verifyAssertion(input.assertion);
    // Only the provider portal may attest its own session provenance. The
    // reference is still resolved against live provider state by org authority.
    if (assertion.provider_session_id && assertion.iss !== "notorganic") throw new GatewayError(403, "permission_error", "Only the provider portal can attach session provenance.", "invalid_product_assertion");
    const now = Math.floor((this.config.now?.() ?? Date.now()) / 1000);
    if (
      typeof assertion.iat !== "number" ||
      typeof assertion.exp !== "number" ||
      assertion.iat > now + DPOP_CLOCK_SKEW_SECONDS ||
      assertion.exp - assertion.iat > ASSERTION_TTL_SECONDS ||
      assertion.exp <= now
    ) {
      throw new GatewayError(
        401,
        "authentication_error",
        "Product assertion must be valid for no more than 60 seconds.",
        "invalid_product_assertion",
      );
    }
    const assertionConsumed = await this.config.store.consumeDpopProof({
      jti: `assertion:${assertion.iss}:${assertion.jti}`,
      expiresAtSeconds: assertion.exp,
    });
    if (!assertionConsumed) {
      throw new GatewayError(
        401,
        "authentication_error",
        "The product assertion has already been exchanged.",
        "product_assertion_replayed",
      );
    }

    const assertionScopes = new Set<string>(assertion.capabilities);
    const requested = scopes(
      input.requestedScope ?? assertion.capabilities.join(" "),
    );
    if ([...requested].some((scope) => !assertionScopes.has(scope))) {
      throw new GatewayError(
        403,
        "permission_error",
        "Requested capability exceeds the product assertion.",
        "scope_escalation",
      );
    }

    const suppliedJkt = input.dpopJwk
      ? await calculateJwkThumbprint(input.dpopJwk)
