import { requireLiveAccount } from "./accountDeletion";
import { mutationGeneric, paginationOptsValidator, queryGeneric } from "convex/server";
import { v } from "convex/values";
import { audit, now, requirePortalSecret } from "./lib";
import { issueGrantFunds } from "./wallet";
import { publicProfileForSession } from "./publicProfile";
import { ACCESS_CREDIT_LIMITS, type AdminCreditCode, type RedeemCreditResult } from "../apps/portal/access-management";

const productScope = v.union(v.literal("keating"), v.literal("twyne"), v.literal("stich"), v.literal("interleave"), v.null());
const admin = { portalSecret: v.string(), actorDid: v.string() };
const credit = { amountMicros: v.number(), productScope, grantExpiresAt: v.union(v.number(), v.null()), reason: v.string() };
const codeFields = { ...credit, tokenHash: v.string(), label: v.string(), maxUses: v.number(), expiresAt: v.number() };

function requireAdmin(portalSecret: string, actorDid: string): void {
  requirePortalSecret(portalSecret);
  const allowed = (process.env.NOTORGANIC_ADMIN_DIDS ?? "").split(/[\s,]+/).filter(Boolean);
  if (!allowed.includes(actorDid)) throw new Error("FORBIDDEN");
}
function text(value: string, name: string, max = 500): void {
  if (!value.trim() || value.length > max || /[\u0000-\u001f\u007f]/.test(value)) throw new Error(`INVALID_${name}`);
}
function hash(value: string): void { if (!/^[a-f0-9]{64}$/.test(value)) throw new Error("INVALID_TOKEN_HASH"); }
function validateCredit(input: {amountMicros: number; grantExpiresAt: number | null; reason: string}): void {
  if (!Number.isSafeInteger(input.amountMicros) || input.amountMicros <= 0 || input.amountMicros > ACCESS_CREDIT_LIMITS.maxAmountMicros) throw new Error("INVALID_AMOUNT");
  if (input.grantExpiresAt !== null && (!Number.isSafeInteger(input.grantExpiresAt) || input.grantExpiresAt <= now())) throw new Error("INVALID_GRANT_EXPIRY");
  text(input.reason, "REASON");
}
function validateCode(input: any): void {
  validateCredit(input); hash(input.tokenHash); text(input.label, "LABEL", 100);
  if (!Number.isSafeInteger(input.maxUses) || input.maxUses < 1 || input.maxUses > ACCESS_CREDIT_LIMITS.maxUses || input.amountMicros * input.maxUses > ACCESS_CREDIT_LIMITS.maxBudgetMicros) throw new Error("INVALID_CODE_BUDGET");
  if (!Number.isSafeInteger(input.expiresAt) || input.expiresAt <= now()) throw new Error("INVALID_CODE_EXPIRY");
  if (input.grantExpiresAt !== null && input.grantExpiresAt < input.expiresAt) throw new Error("GRANT_EXPIRES_BEFORE_CODE");
}
function codeProjection(row: any): AdminCreditCode {
  return { id: row._id, label: row.label, amountMicros: row.amountMicros, productScope: row.productScope,
    maxUses: row.maxUses, uses: row.uses, expiresAt: row.expiresAt, grantExpiresAt: row.grantExpiresAt,
    createdAt: row.createdAt, createdBy: row.createdBy, revokedAt: row.revokedAt ?? null };
}
async function requireKnownAccount(ctx: any, did: string): Promise<void> {
  if (!/^did:(plc|web):[^\s]+$/.test(did) || did.length > 2048) throw new Error("INVALID_DID");
  const account = await ctx.db.query("didAccounts").withIndex("by_did", (q: any) => q.eq("did", did)).unique();
  if (account && (account.deletedAt !== undefined || account.recoveryState !== "active")) throw new Error("ACCOUNT_UNAVAILABLE");
  const wallet = await ctx.db.query("wallets").withIndex("by_did", (q: any) => q.eq("did", did)).unique();
  const oauth = await ctx.db.query("oauthSessions").withIndex("by_did", (q: any) => q.eq("did", did)).unique();
  if (!account && !wallet && !oauth) throw new Error("ACCOUNT_NOT_FOUND");
}
export const directGrant = mutationGeneric({ args: { ...admin, ...credit, did: v.string(), requestId: v.string() }, handler: async (ctx, args) => {
  requireAdmin(args.portalSecret, args.actorDid); await requireLiveAccount(ctx, args.actorDid); validateCredit(args); text(args.requestId, "REQUEST_ID", 128); await requireKnownAccount(ctx, args.did);
  const grantId = await issueGrantFunds(ctx, { did: args.did, program: "admin_credit", amountMicros: args.amountMicros,
    productScope: args.productScope, expiresAt: args.grantExpiresAt, idempotencyKey: `admin:${args.actorDid}:${args.requestId}`, reason: args.reason }, args.actorDid);
  return { grantId, amountMicros: args.amountMicros, remainingMicros: (await ctx.db.get(grantId)).remainingMicros };
} });
