  } catch {
    return c.json({ error: { message: "Expected a JSON body.", code: "invalid_body" } }, 400);
  }
  let identifier: string | null;
  try {
    identifier = deps.unison
      ? typeof handle === "string" && handle.length <= 256
        ? (await deps.unison.call<{ identifier: string | null }>("/internal/account/normalize", { identifier: handle })).identifier
        : null
