    if (identifier !== null && typeof identifier !== "string") throw new Error("Invalid native login response");
  } catch { return c.json({ error: { message: "Sign-in is temporarily unavailable.", code: "login_unavailable" } }, 503); }
  if (identifier === null) {
    return c.json({ error: { message: "Enter your Not Organic name, full handle, or DID.", code: "invalid_handle" } }, 400);
  }
  try {
    const state: SignInAttemptState = {};
    const pending = continuation === undefined ? null : validContinuation(continuation);
    if (continuation !== undefined && !pending) {
      return c.json({ error: { message: "This app connection has expired. Return to the app and start again.", code: "continuation_expired" } }, 400);
