import { readFileSync, existsSync } from "node:fs";

const PREFIX = process.argv[2] ?? "notorganic-full-20261023";
const DIR = "/home/diogenes/Projects/apps/twyne/reports/app-evals";
const ROOT = "/home/diogenes/Projects/apps/twyne/evals";
const load = (suite: string) => {
  const path = `${DIR}/${PREFIX}-${suite}.json`;
  return existsSync(path) ? JSON.parse(readFileSync(path, "utf8")) : null;
};
const jsonl = (p: string) =>
  readFileSync(`${ROOT}/${p}`, "utf8").split("\n").filter((l) => l.trim()).map((l) => JSON.parse(l));
const pct = (v: number | null | undefined) => (typeof v === "number" ? v.toFixed(2) : "  - ");

for (const suite of ["room", "rubric", "rewrite", "dossier", "interview"]) {
  const r = load(suite);
  if (!r) continue;
  console.log(`\n=== ${suite} (${r.cases.length} cases, ${r.errors} errors) ${r.usage ? `calls ${r.usage.calls}, tok ${r.usage.inputTokens}/${r.usage.outputTokens}` : ""}`);
  for (const [k, v] of Object.entries(r.summary) as any) console.log(`  ${k.padEnd(24)} ${pct(v.mean)} (n=${v.n})`);
}

const room = load("room");
if (room) {
  const cases = new Map(jsonl("app/cases/room.jsonl").map((c: any) => [c.case_id, c]));
  const byKind: Record<string, [number, number]> = {};
  const byEditor: Record<string, [number, number]> = {};
  console.log("\n--- room per case: coverage / visible / faithful / helpful / anchored");
  for (const c of room.cases) {
    const s = c.scores;
    console.log(`  ${c.case_id.padEnd(28)} ${pct(s.plant_coverage?.score)} ${pct(s.plant_coverage_visible?.score)} ${pct(s.faithfulness?.score)} ${pct(s.helpfulness?.score)} ${pct(s.anchored?.score)}  ${s.plant_coverage?.explanation ?? c.error ?? ""}`);
    const tc: any = cases.get(c.case_id);
    if (!tc || !c.raw) continue;
    const missed = new Set(((s.plant_coverage?.explanation ?? "").match(/p\d+/g) ?? []) as string[]);
    for (const p of tc.plants) {
      const k = (byKind[p.kind] ??= [0, 0]);
      k[1] += 1;
      if (!missed.has(p.id)) k[0] += 1;
    }
    for (const n of c.raw.notes ?? []) {
      const e = (byEditor[n.personaId] ??= [0, 0]);
      e[1] += 1;
      if (n.anchor) e[0] += 1;
    }
  }
  console.log("\n--- room plants noticed by kind");
  for (const [k, [hit, n]] of Object.entries(byKind)) console.log(`  ${k.padEnd(20)} ${hit}/${n}`);
  console.log("\n--- notes anchored by editor");
  for (const [k, [hit, n]] of Object.entries(byEditor)) console.log(`  ${k.padEnd(10)} ${hit}/${n}`);
  const judged = room.cases.flatMap((c: any) => [c.scores.faithfulness?.explanation, c.scores.helpfulness?.explanation]).filter(Boolean);
  const generic = judged.join("; ").match(/(\w+): generic/g) ?? [];
  const poor = judged.join("; ").match(/(\w+): poor/g) ?? [];
  console.log("\n--- judged generic:", generic.length, JSON.stringify(Object.entries(generic.reduce((m: any, g: string) => ((m[g.split(":")[0]] = (m[g.split(":")[0]] ?? 0) + 1), m), {}))));
  console.log("--- judged poor:", poor.length, JSON.stringify(Object.entries(poor.reduce((m: any, g: string) => ((m[g.split(":")[0]] = (m[g.split(":")[0]] ?? 0) + 1), m), {}))));
}

const rubric = load("rubric");
if (rubric) {
  console.log("\n--- rubric grades");
  for (const c of rubric.cases) {
    const g = c.raw ?? {};
    console.log(`  ${c.case_id.padEnd(30)} grade ${String(g.grade ?? "?").padEnd(3)} combined ${String(g.combined ?? "?").padEnd(4)} judges ${String(g.judgeMean ?? "?").slice(0, 4).padEnd(4)} ev ${g.evidence?.score ?? "-"} in ${g.integrity?.score ?? "-"} su ${g.sufficiency?.score ?? "-"} fit ${g.targetFit?.score ?? "-"}  ${c.scores.weakness_recall?.explanation ?? ""}`);
  }
}

for (const suite of ["rewrite", "interview", "dossier"]) {
  const r = load(suite);
  if (!r) continue;
  console.log(`\n--- ${suite} misses`);
  for (const c of r.cases) {
    const misses = Object.entries(c.scores as Record<string, any>).filter(([, v]) => typeof v.score === "number" && v.score < 1);
    if (misses.length || !c.ok) console.log(`  ${c.case_id}: ${c.error ?? misses.map(([k, v]) => `${k}=${pct(v.score)} (${v.label ?? ""} ${String(v.explanation ?? "").slice(0, 120)})`).join(" | ")}`);
  }
}

