function isOpenAiCompatibleProvider(type: AiProviderConfig["type"]): boolean {
  return (
    type === "openai-compatible" ||
    type === "deepseek" ||
    type === "openrouter" ||
    type === "ollama" ||
    type === "zai" ||
    type === "minimax"
  );
}

