export function usesOpenAiResponsesApi(
  config: Pick<AiProviderConfig, "apiMode">,
): boolean {
export const get = queryGeneric({
  args: { did: v.string() },
  handler: async (ctx, args) => {
    await requireDid(ctx, args.did);
    const wallet = await ctx.db.query("wallets").withIndex("by_did", (q) => q.eq("did", args.did)).unique();
    const grants = await ctx.db
      .query("grantLots")
      .withIndex("by_did_expiry", (q) => q.eq("did", args.did))
      .take(256);
    return {
      wallet,
      availableGrantMicros: grants
        .filter((lot) => lot.expiresAt === null || lot.expiresAt > now())
        .reduce((sum, lot) => sum + lot.remainingMicros, 0),
    };
  },
});
