import { useState } from "react";
import { portalApi, type UsageRow, type WalletView } from "../api";
import { useCountUp } from "../juice";
import {
  Empty,
  Panel,
  productLabel,
  StatusPill,
  timestamp,
  usd,
  usdRounded,
  useLoader,
} from "../ui";

function Balance({ wallet }: { wallet: WalletView }) {
  const spendable = wallet.balanceMicros + wallet.availableGrantMicros - wallet.debtMicros;
  // The figure people opened the portal to check, so it is lifted out of the
  // table and set at display scale. It rolls from its previous value, which
  // means a refresh that changed nothing does not move and a refresh that
  // spent something visibly falls.
  const rolling = useCountUp(spendable);

  return (
    <>
      <p className="balance-label">Spendable now</p>
      <p className="balance">{usdRounded(rolling)}</p>

      <dl className="overview overview-row">
        <div>
          <dt>Cash balance</dt>
          <dd>{usd(wallet.balanceMicros)}</dd>
        </div>
        <div>
          <dt>Grants</dt>
          <dd>{usd(wallet.availableGrantMicros)}</dd>
        </div>
        <div>
          <dt>Reserved</dt>
          <dd>
            {usd(wallet.reservedMicros)}
            {wallet.reservedMicros > 0 && <span className="hint"> held for requests in flight</span>}
          </dd>
        </div>
        <div>
          <dt>Debt</dt>
          <dd>{usd(wallet.debtMicros)}</dd>
        </div>
      </dl>
      {wallet.hostedInferenceBlocked && (
        <p className="notice notice-bad">

export interface WalletView {
  currency: "USD_MICROS";
  balanceMicros: number;
  reservedMicros: number;
  debtMicros: number;
  availableGrantMicros: number;
  hostedInferenceBlocked: boolean;
}

export interface UsageRow {
  _id: string;
  requestId: string;
  product: string;
  feature: string;
  model: string;
  "baste",
  "frenzy",
  "traction",
  // The provider's own account portal. It is a first-party client of this
  // gateway rather than a billable product: wallet, usage, and account are
  // keyed by DID, and its Creem catalog is empty unless an operator adds one.
  "notorganic",
] as const;
export const ProductIdSchema = z.enum(PRODUCT_IDS);
export type ProductId = z.infer<typeof ProductIdSchema>;
