import { startLocalApp } from "./local-app";
import { connectMcp } from "./drivers";
import { readJsonl } from "./suites/load";
import { parseJudgeOutput } from "../../src/utils/llm-parsing";
const realFetch = globalThis.fetch;
const seen: Array<Record<string, unknown>> = [];
const pending: Promise<void>[] = [];
globalThis.fetch = (async (input: any, init?: any) => {
  const url = typeof input === "string" ? input : input instanceof Request ? input.url : String(input);
  let reqBody = "";
  if (url.includes("/chat/completions")) reqBody = input instanceof Request ? await input.clone().text() : typeof init?.body === "string" ? init.body : "";
  const res = await realFetch(input, init);
  if (url.includes("/chat/completions") && /JUDGE TASK/.test(reqBody) && /As [^,]+, give the draft a single integer score/.test(reqBody)) {
    const model = JSON.parse(reqBody).model;
    pending.push(res.clone().text().then((t) => {
      try {
        const m = JSON.parse(t).choices?.[0];
        const content = typeof m?.message?.content === "string" ? m.message.content : "";
        seen.push({ model, status: res.status, finish: m?.finish_reason, content: content.length, reasoning: String(m?.message?.reasoning_content ?? m?.message?.reasoning ?? "").length, parsed: !!parseJudgeOutput(content), head: content.slice(0, 220) });
      } catch { seen.push({ model, status: res.status, raw: t.slice(0, 200) }); }
    }));
  }
  return res;
}) as typeof fetch;
const app = await startLocalApp({ model: "notorganic" });
const w = await app.newWriter("judge-probe");
const mcp = await connectMcp({ apiUrl: app.url, token: w.token, fetch: app.fetch });
const c = readJsonl<any>("app/cases/rubric.jsonl").find((x) => x.case_id === "rubric-sourdough-strong");
const g = await mcp.call("twyne_grade_draft", { draftText: c.draftText, brief: c.brief }) as any;
await Promise.all(pending);
console.log("judged:", g.judges.map((j: any) => j.personaId).join(","), "| unjudged:", (g.unjudged ?? []).join(","));
for (const s of seen) console.log(JSON.stringify(s));
await mcp.close(); await app.close();
EOF
