    const cost = price(operation === "search" ? settings.searchPriceMicrousd : settings.fetchPriceMicrousd);
    if (!body || typeof body !== "object" || Array.isArray(body)) invalid("An object body is required.");
    const b = body as Record<string, unknown>;
    let target: URL | undefined; let query: Record<string, unknown> = {};
    if (operation === "fetch") target = await publicUrl(this.config, b.url);
    else {
      if (typeof b.query !== "string" || !b.query.trim() || b.query.length > 4096) invalid("query must contain 1 to 4096 characters.");
      const count = b.max_results ?? 10;
      if (!Number.isInteger(count) || Number(count) < 1 || Number(count) > 50) invalid("max_results must be 1 to 50.");
      if (b.freshness !== undefined && !["day", "week", "month", "year"].includes(String(b.freshness))) invalid("Unsupported freshness.");
      query = { query: b.query, max_results: count, mode: "pro", ...(b.freshness ? { published_after: ({ day: "1d", week: "7d", month: "1mo", year: "1y" } as Record<string, string>)[String(b.freshness)] } : {}) };
    }
    const reservation = await begin(this.config, principal, `web-${operation}`, key, hash, cost);
    if (reservation.replay) return publicResult(reservation.replay);
    const { id } = reservation;
    let accepted = false; let dispatched = false;
    try {
      signal?.throwIfAborted();
      const cached = target && this.cache.get(target.href);
      let data = cached && cached.expires > Date.now() ? cached.data : undefined;
      if (!data) {
        const now = Date.now(); this.calls = this.calls.filter(x => now - x < 3600_000);
        if (this.calls.filter(x => now - x < 1000).length >= 10 || this.calls.length >= (settings.hourlyLimit ?? 1000)) throw new GatewayError(429, "rate_limit_error", "Web request rate limit reached.", "web_rate_limited");
        this.calls.push(now);
        const origin = settings.apiOrigin ?? "https://api.keenable.ai";
        // Indexed mode avoids an opaque live-fetch redirect chain inside Keenable.
        const path = target ? `/v1/fetch?url=${encodeURIComponent(target.href)}&max_chars=200001&live=false` : "/v1/search";
        dispatched = true;
        const timeout = AbortSignal.timeout(30_000);
        const response = await (this.config.fetch ?? fetch)(`${origin}${path}`, { method: target ? "GET" : "POST", redirect: "error", signal: signal ? AbortSignal.any([signal, timeout]) : timeout, headers: { "X-API-Key": settings.apiKey, "content-type": "application/json" }, ...(target ? {} : { body: JSON.stringify(query) }) });
        if (!response.ok) {
          // A server error or timeout does not establish non-acceptance upstream.
          if ([400, 401, 403, 404, 422, 429].includes(response.status)) dispatched = false;
          throw new GatewayError(response.status === 429 ? 429 : 502, "api_error", "Web upstream rejected the request.", "web_upstream_error");
        }
        accepted = true; await this.config.store.markAccepted({ requestId: id });
        const payload = await boundedJson(response);
        if (target) {
          if (payload.url !== undefined) await publicUrl(this.config, payload.url);
          if (typeof payload.content !== "string") throw new GatewayError(502, "api_error", "Missing Markdown.", "invalid_upstream_response");
          if (payload.content.length > 200_000) invalid("Fetched page exceeds 200k characters.", 413);
          data = { url: payload.url ?? target.href, title: typeof payload.title === "string" ? payload.title : "", markdown: payload.content, fetched_at: new Date().toISOString(), usage: { requests: 1 } };
          if (this.cache.size >= 256) this.cache.delete(this.cache.keys().next().value!);
          this.cache.set(target.href, { expires: now + 60_000, data });
        } else {
          if (!Array.isArray(payload.results)) throw new GatewayError(502, "api_error", "Missing search results.", "invalid_upstream_response");
          data = { results: payload.results.slice(0, Number(query.max_results)).filter((r: any) => r && typeof r === "object" && typeof r.url === "string" && /^https:\/\//.test(r.url)).map((r: any) => ({ url: r.url, title: String(r.title ?? ""), snippet: String(r.snippet ?? r.description ?? ""), ...(typeof r.published_at === "string" ? { published_at: r.published_at } : {}) })), usage: { requests: 1 } };
        }
      }
      await this.config.store.settleWithResponse({ requestId: id, accountId: principal.accountId, actualCostMicrousd: cost, usage: { requests: 1 }, response: record(id, principal, hash, data) });
      return data;
    } catch (error) {
      if (accepted || dispatched) await this.config.store.reconcile({ requestId: id, conservativeCostMicrousd: cost, reason: "web_response_unavailable" });
      else await this.config.store.release({ requestId: id, reason: "web_not_accepted" });
      throw error;
    }
  }
}

