content.content:
/**
 * System One (TypeSafe) answers for the editorial review gate: every note is
 * judged fit to release, so the gate's plumbing runs without a redraft.
 */
function judgementAnswers(request: JudgementRequest) {
  return Object.fromEntries(
    Object.entries(request.questions ?? {}).map(([id, question]) => {
      if (question.type === "noul") return [id, { type: "noul", noul: 0.05 }];
      if (question.type === "choice") {
        const options = Object.keys((question.criteria ?? {}) as Record<string, unknown>);
        const choice = options[0] ?? "";
        return [id, { type: "choice", choice, probabilities: { [choice]: 1 }, confidence: 0.9 }];
      }
      const levels = Array.isArray(question.criteria) ? question.criteria : ["", ""];
      const top = levels.length - 1;
      return [
        id,
        {
          type: "score",
          score: top,
          legend: Object.fromEntries(levels.map((text, i) => [String(i), String(text)])),
          probabilities: { [String(top)]: 1 },
          confidence: 0.9,
        },
      ];
    }),
  );
}

export async function startMockModel(): Promise<MockModelServer> {
  const calls: MockModelServer["calls"] = [];
  const server: Server = createServer(async (req, res) => {
    if (req.method === "POST" && req.url?.endsWith("/v1/systemone")) {
      const request = JSON.parse(await readBody(req)) as JudgementRequest;
      calls.push({ kind: "system-one", model: request.model ?? "jev" });
      res.writeHead(200, { "content-type": "application/json" });
      res.end(
        JSON.stringify({
          model: "jev-mock",
          answers: judgementAnswers(request),
          usage: { input_tokens: 400, output_tokens: 0 },
        }),
      );
      return;
    }
    if (req.method !== "POST" || !req.url?.endsWith("/chat/completions")) {
      res.writeHead(404).end();
      return;
    }
    let body: ChatBody;
    try {
      body = JSON.parse(await readBody(req)) as ChatBody;
    } catch {
      res.writeHead(400).end();
      return;
    }
    const model = body.model ?? "mock";
    const reply = scriptedReply(body);
    calls.push({ kind: reply.kind, model });
    if (body.stream) {
      res.writeHead(200, { "content-type": "text/event-stream" });
      res.end(streamChunks(model, reply));
      return;
    }
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify(completion(model, reply)));
  });
  await new Promise<void>((resolve) =>
    server.listen(0, "127.0.0.1", () => resolve()),
  );
  const { port } = server.address() as { port: number };
  return {
    url: `http://127.0.0.1:${port}`,
    calls,
    close: () =>
      new Promise<void>((resolve) => server.close(() => resolve())),
  };
}

