import { startLocalApp } from "./local-app";
import { connectMcp } from "./drivers";
import { readJsonl } from "./suites/load";
const realFetch = globalThis.fetch;
const reviews: Array<{ state: Record<string, string>; answers: Record<string, any> }> = [];
const pending: Promise<void>[] = [];
globalThis.fetch = (async (input: any, init?: any) => {
  const url = typeof input === "string" ? input : input instanceof Request ? input.url : String(input);
  const res = await realFetch(input, init);
  if (url.includes("/v1/systemone")) {
    const body = typeof init?.body === "string" ? JSON.parse(init.body) : {};
    pending.push(res.clone().json().then((j: any) => { reviews.push({ state: body.state ?? {}, answers: j.answers ?? {} }); }).catch(() => {}));
  }
  return res;
}) as typeof fetch;
const app = await startLocalApp({ model: "notorganic", research: "off", systemOne: "direct" });
const w = await app.newWriter("veto-probe");
const mcp = await connectMcp({ apiUrl: app.url, token: w.token, fetch: app.fetch });
const c = readJsonl<any>("app/cases/room.jsonl").find((x) => x.case_id === "room-essay-shortwave");
try { const r = await mcp.call("twyne_convene_room", { draftText: c.draftText, brief: c.brief, personaIds: ["scholar", "devil"] }) as any; console.log("convene ok:", r.notes.length); }
catch (e) { console.log("convene failed:", (e as Error).message); }
await Promise.all(pending);
const draft = c.draftText as string;
for (const r of reviews) {
  const p = r.answers.draft_claim_unanchored?.noul;
  if (typeof p !== "number" || p < 0.75) continue;
  const passage = String(r.state.policyPassage ?? "");
