p = "convex/agents.ts"
s = open(p).read()

# 1. A typed error for a note the editorial gate withheld.
old = '''/** The drafting loop writes notes; a rubric judge never enters it. */'''
new = '''/**
 * A note the editorial review would not release: vetoed by the policy gate,
 * or still below the quality bar after its repairs. This is a verdict about
 * one editor's note, not a provider failure, so a room drops that editor and
 * keeps the rest — as the browser's own gate does — instead of failing all
 * five.
 */
export class EditorialNoteWithheld extends Error {
  constructor(readonly reason: string) {
    super(`editorial-draft-${reason}`);
    this.name = "EditorialNoteWithheld";
  }
}

/** The drafting loop writes notes; a rubric judge never enters it. */'''
assert old in s, "anchor 1"
s = s.replace(old, new, 1)

# 2. Throw it for review outcomes; a provider failure keeps the plain error.
old = '''    throw new Error(`editorial-draft-${result.receipt.reason ?? "withheld"}`);'''
new = '''    const reason = result.receipt.reason ?? "withheld";
    if (reason === "generation-unavailable")
      throw new Error(`editorial-draft-${reason}`);
    throw new EditorialNoteWithheld(reason);'''
assert s.count(old) == 1, "anchor 2"
s = s.replace(old, new, 1)

# 3. The gate sees every passage the note quoted, not only the first.
old = '''    review: (candidate) =>
      reviewEditorialNote(systemOneCaller, {
        note: candidate.text,
        quote: candidate.anchor,'''
new = '''    review: (candidate) =>
      reviewEditorialNote(systemOneCaller, {
        note: candidate.text,
        // A note can quote several passages (`anchors`); the grounding check
        // must see all of them, or a claim about the second reads as
        // unanchored and the note is vetoed for evidence it did quote.
        quote: [...new Set([candidate.anchor, ...(candidate.value.anchors ?? [])])]
          .filter((passage): passage is string => !!passage?.trim())
          .join("\\n\\n"),'''
assert s.count(old) == 1, "anchor 3"
s = s.replace(old, new, 1)

# 4. A room keeps the editors whose notes were released.
old = '''    } catch (err) {
      throw reportedApplicationError(
        "agents.convene-room",
        "provider_unavailable",
        err,
        { recovery: "retry" },
        {
          provider: provider.label,
          model: provider.modelId,
        },
      );
    }
  });

  const results = await Promise.all(tasks);
  return results.map((r, i) => ({
    personaId: args.personas[i].id,
    ...r,
  }));
}'''
new = '''    } catch (err) {
      if (err instanceof EditorialNoteWithheld) return err;
      throw reportedApplicationError(
        "agents.convene-room",
        "provider_unavailable",
        err,
        { recovery: "retry" },
        {
          provider: provider.label,
          model: provider.modelId,
        },
      );
    }
  });

  const results = await Promise.all(tasks);
  const released = results.flatMap((r, i) =>
    r instanceof EditorialNoteWithheld
      ? []
      : [{ personaId: args.personas[i].id, ...r }],
  );
  // Editors whose notes the review withheld are simply absent; the caller
  // learns who from the ids. Only a room with nothing to show is an error.
  if (released.length === 0) {
    const first = results.find((r) => r instanceof EditorialNoteWithheld);
    throw reportedApplicationError(
      "agents.convene-room",
      "provider_unavailable",
      first,
      { recovery: "retry" },
      { provider: provider.label, model: provider.modelId },
    );
  }
  return released;
}'''
assert s.count(old) == 1, "anchor 4"
s = s.replace(old, new, 1)
open(p, "w").write(s)

p = "convex/integrationAi.ts"
s = open(p).read()
old = '''    const notes = await conveneRoomCore(
      ctx,
      callerFromTokenIdentifier(ownerId),
      args,
    );
    return {
      notes: notes.map((note, index) =>
        editorNote(args.personas[index] as AgentPersona, note),
      ),
    };'''
new = '''    const notes = await conveneRoomCore(
      ctx,
      callerFromTokenIdentifier(ownerId),
      args,
    );
    const released = new Set(notes.map((note) => note.personaId));
    return {
      notes: notes.map((note) =>
        editorNote(
          args.personas.find((p) => p.id === note.personaId) as AgentPersona,
          note,
        ),
      ),
      // Editors whose notes the editorial review would not release.
      withheld: args.personas.map((p) => p.id).filter((id) => !released.has(id)),
    };'''
assert s.count(old) == 1, "integration anchor"
s = s.replace(old, new, 1)
open(p, "w").write(s)
print("ok")
EOF
timeout 400 npx tsc -p convex/tsconfig.json --noEmit 2>&1 | grep -v "extraction.test.ts" | head -8; echo convex-tsc-done

