43	function renderObservation(o: Observation): string {
44	  return `${o.field}: ${o.current ?? ""} -> ${o.suggested ?? ""} (${o.reason ?? ""})`;
45	}
46	
47	/** What an observation claims about the draft, without the fix it proposes. */
48	function claimOf(o: Observation): string {
49	  return `${o.field}: ${o.current ?? ""} (${o.reason ?? ""})`;
50	}
51	
52	/**
53	 * The brief fields a drift names. Issues lead with their fields
54	 * ("Tone and audience: ..."); without that label the whole sentence is read.
55	 */
56	function driftFields(issue: string): string[] {
57	  const label = issue.includes(":") ? issue.slice(0, issue.indexOf(":")) : issue;
58	  const lower = label.toLowerCase().replace(/success ?signal/g, "successsignal").replace(/working ?title/g, "workingtitle");
59	  return FIELDS.filter((field) => lower.includes(field.toLowerCase()));
60	}
