import { afterEach, describe, expect, spyOn, test } from "bun:test";
import { extract, isAvailable } from "./extraction";
import * as notorganic from "./lib/notorganic";
import * as entitlement from "./lib/entitlement";
import * as limits from "./lib/rateLimit";
import type {
  ExtractionRequest,
  ExtractionResult,
} from "../src/utils/extraction";
import contract from "../src/utils/extraction-contract-v1.json";

const cleanup: Array<() => void> = [];
afterEach(() =>
  cleanup
    .splice(0)
    .reverse()
    .forEach((off) => off()),
);
function env(values: Record<string, string | undefined>) {
  for (const [key, value] of Object.entries(values)) {
    const before = process.env[key];
    if (value === undefined) delete process.env[key];
    else process.env[key] = value;
    cleanup.push(() => {
      if (before === undefined) delete process.env[key];
      else process.env[key] = before;
    });
  }
}
const request: ExtractionRequest = {
  state: "Ada arrived.",
  fields: { name: { type: "text" } },
};
const body = {
  model: "extraction-clairic/clairic",
  truncated: false,
  answers: { name: { type: "text", value: "Ada", span: [0, 3] } },
  usage: { input_tokens: 10, output_tokens: 0 },
};
function fixture() {
  const enabled = spyOn(notorganic, "notOrganicEnabled").mockReturnValue(true);
  const token = spyOn(
    notorganic,
    "issueNotOrganicAccessToken",
  ).mockResolvedValue({
    accessToken: "test",
    dpop: {} as notorganic.DpopKeyPair,
  });
  const upstream = spyOn(notorganic, "providerJsonRequest").mockResolvedValue(
    body,
  );
  const pro = spyOn(entitlement, "userIsPro").mockResolvedValue(false);
  const limit = spyOn(limits, "consumeRateLimit").mockResolvedValue(undefined);
  const direct = spyOn(globalThis, "fetch").mockRejectedValue(
    new Error("Unexpected direct call"),
  );
  for (const spy of [enabled, token, upstream, pro, limit, direct])
    cleanup.push(() => spy.mockRestore());
  let identity: { subject: string; tokenIdentifier: string } | null = {
    subject: "writer",
    tokenIdentifier: "issuer|writer",
  };
  let linked = true;
  const ctx = {
    auth: { getUserIdentity: async () => identity },
    runQuery: async () =>
      linked ? { did: "did:plc:writer", sessionVersion: 2 } : null,
  };
  return {
    enabled,
    token,
    upstream,
    pro,
    limit,
    direct,
    signedOut: () => {
      identity = null;
    },
    unlinked: () => {
      linked = false;
    },
    run: (input = request) =>
      (
        extract as unknown as {
          _handler: (
            ctx: unknown,
            args: ExtractionRequest,
          ) => Promise<ExtractionResult>;
        }
      )._handler(ctx, input),
    available: () =>
      (
        isAvailable as unknown as {
          _handler: () => Promise<{ available: boolean; transport: string }>;
        }
      )._handler(),
  };
}

describe("Clairic action boundaries", () => {
  test("signed-out callers never reach token exchange, tier lookup or provider", async () => {
    const f = fixture();
    f.signedOut();
    expect(await f.run()).toMatchObject({ ok: false, error: "signed out" });
    expect(f.pro).not.toHaveBeenCalled();
    expect(f.token).not.toHaveBeenCalled();
    expect(f.upstream).not.toHaveBeenCalled();
  });
  test("unlinked callers never reach extraction provider", async () => {
    const f = fixture();
    f.unlinked();
    expect(await f.run()).toMatchObject({
      ok: false,
      error: "account not linked",
    });
    expect(f.token).not.toHaveBeenCalled();
    expect(f.upstream).not.toHaveBeenCalled();
  });
  test("linked writer uses the account capability and receives validated values", async () => {
    const f = fixture();
    expect(await f.run()).toMatchObject({
      ok: true,
      transport: "notorganic",
      answers: body.answers,
    });
    expect(f.token).toHaveBeenCalledWith({
      did: "did:plc:writer",
      sessionVersion: 2,
      feature: "extraction",
      capabilities: ["extraction:run"],
    });
    expect(f.direct).not.toHaveBeenCalled();
  });
  test("rate limit refusal is returned without provider dispatch", async () => {
    const f = fixture();
    f.limit.mockRejectedValue(new limits.RateLimitError("private", 1000));
    expect(await f.run()).toMatchObject({ ok: false, error: "rate limited" });
    expect(f.upstream).not.toHaveBeenCalled();
  });
  test("unrelated exceptions do not become rate limits or echo the draft", async () => {
    const f = fixture();
    f.pro.mockRejectedValue(new Error(request.state));
    expect(await f.run()).toEqual({
      ok: false,
      transport: "notorganic",
      error: "provider",
    });
  });
  test("upstream authorization denial stays an authorization failure", async () => {
    const f = fixture();
    f.upstream.mockRejectedValue(
      new Error(`Not Organic API failed (403): ${request.state}`),
    );
    expect(await f.run()).toEqual({
      ok: false,
      transport: "notorganic",
      error: "unauthorized",
    });
  });
  for (const example of contract.cases.filter(
    (example) =>
      !example.valid && example.name !== "ambiguous repeated unicode source",
  )) {
    test(`rejects malformed hosted response: ${example.name}`, async () => {
      const f = fixture();
      f.upstream.mockResolvedValue({ ...body, answers: example.answers });
      expect(await f.run(example.request as ExtractionRequest)).toMatchObject({
        ok: false,
        error: "provider",
      });
    });
  }
  test("rejects negative and non-finite usage instead of returning it to Convex", async () => {
    for (const n of [-1, Infinity, NaN]) {
      const f = fixture();
      f.upstream.mockResolvedValue({
        ...body,
        usage: { input_tokens: n, output_tokens: 0 },
      });
      expect(await f.run()).toMatchObject({ ok: false, error: "provider" });
    }
  });
  // Each case overrides one variable of the otherwise-permitted local setup.
  const refusals: Array<[string, Record<string, string | undefined>]> = [
    ["production", { NODE_ENV: "production" }],
    ["unset environment", { NODE_ENV: undefined }],
    [
      "hosted development",
      { CONVEX_CLOUD_URL: "https://example.convex.cloud" },
    ],
    ["no explicit opt in", { TWYNE_ALLOW_DIRECT_EXTRACTION: undefined }],
  ];
  for (const [label, overrides] of refusals) {
    test(`refuses direct credentials in ${label}`, async () => {
      const f = fixture();
      f.enabled.mockReturnValue(false);
      env({
        NODE_ENV: "development",
        TWYNE_ALLOW_DIRECT_EXTRACTION: "1",
        CONVEX_CLOUD_URL: "http://127.0.0.1:3210",
        CLOUDFLARE_AI_API_TOKEN: "fixture",
        CLOUDFLARE_ACCOUNT_ID: "fixture",
        ...overrides,
      });
      expect(await f.available()).toEqual({
        available: false,
        transport: "none",
      });
      expect(await f.run()).toMatchObject({ ok: false, error: "unconfigured" });
      expect(f.direct).not.toHaveBeenCalled();
      expect(f.upstream).not.toHaveBeenCalled();
    });
  }
  test("explicit local development permits direct extraction, still validates responses", async () => {
    const f = fixture();
    f.enabled.mockReturnValue(false);
    env({
      NODE_ENV: "development",
      TWYNE_ALLOW_DIRECT_EXTRACTION: "1",
      CONVEX_CLOUD_URL: "http://127.0.0.1:3210",
      CLOUDFLARE_AI_API_TOKEN: "fixture",
      CLOUDFLARE_ACCOUNT_ID: "fixture",
    });
    f.direct.mockResolvedValue(
      Response.json({ result: { ...body, model: "clairic" } }),
    );
    expect(await f.available()).toEqual({
      available: true,
      transport: "direct",
    });
    expect(await f.run()).toMatchObject({ ok: true, transport: "direct" });
    f.direct.mockResolvedValue(
      Response.json({
        result: {
          ...body,
          model: "clairic",
          answers: { name: { type: "text", value: "wrong", span: [0, 3] } },
        },
      }),
    );
    expect(await f.run()).toMatchObject({
      ok: false,
      transport: "direct",
      error: "provider",
    });
  });
});

/**
 * The room of editors, convened on a draft through `twyne_convene_room`.
 *
 * Each case plants checkable features in a 550-900 word draft: unsupported
 * claims, weak arguments, bloat, a strong passage worth protecting. The
 * deterministic checks ask whether the room found them, whether each note
 * pinned itself to a passage the writer actually wrote, and whether five
 * editors read like five people. The judge, when enabled, applies the same
 * faithfulness and helpfulness rubrics as `evals/judge.ts` to every note.
 */
import {
  askJev,
  judged,
  judgeFaithfulness,
  judgeHelpfulness,
  judgeNoteValue,
  JEV_NOTE_QUESTIONS,
} from "../judges";
import {
  contains,
  distinctness,
  fold,
  mean,
  ratio,
  sharesRun,
  spansOverlap,
  visibleToEditors,
  type Score,
} from "../scoring";
import { readJsonl } from "./load";
import type { EditorNote, ProjectBrief, Suite } from "./types";

interface Plant {
  id: string;
  kind: string;
  passage: string;
  expectedEditors: string[];
  note: string;
}

export interface RoomCase {
  case_id: string;
  genre: string;
  brief: ProjectBrief;
  draftText: string;
  plants: Plant[];
}

function notesOf(raw: unknown): EditorNote[] {
  const notes = (raw as { notes?: unknown })?.notes;
  return Array.isArray(notes) ? (notes as EditorNote[]) : [];
}

/** Editors whose notes the app's editorial review would not release. */
function withheldOf(raw: unknown): string[] {
  const withheld = (raw as { withheld?: unknown })?.withheld;
  return Array.isArray(withheld) ? (withheld as string[]) : [];
}

function anchorsOf(note: EditorNote): string[] {
  if (note.anchors?.length) return note.anchors;
  return note.anchor ? [note.anchor] : [];
}

function covers(draft: string, note: EditorNote, plant: Plant): boolean {
  return (
    anchorsOf(note).some((anchor) =>
      spansOverlap(draft, anchor, plant.passage),
    ) || sharesRun(note.text, plant.passage, 5)
  );
}

export function renderNotes(notes: EditorNote[]): string {
  return notes
    .map((note) => {
      const head = `[${note.personaName ?? note.personaId}] (${note.type ?? "note"}, ${note.provider ?? "?"})`;
      const anchor = note.anchor ? `\n  > ${note.anchor}` : "";
      return `${head} ${note.text}${anchor}`;
    })
    .join("\n\n");
}

export const roomSuite: Suite<RoomCase> = {
  name: "room",
  surface: "MCP twyne_convene_room",
  load: () => readJsonl<RoomCase>("app/cases/room.jsonl"),

  async run({ mcp }, testCase) {
    const raw = await mcp.call("twyne_convene_room", {
      draftText: testCase.draftText,
      brief: testCase.brief,
    });
    return { raw, output: renderNotes(notesOf(raw)) };
  },

  async score({ judge, jev }, testCase, raw) {
    const draft = testCase.draftText;
    const notes = notesOf(raw);
    const written = notes.filter((note) => note.text?.trim());
    const anchors = notes.flatMap(anchorsOf);
    const verbatim = anchors.filter((anchor) => contains(draft, anchor));
    const visible = testCase.plants.filter((plant) =>
      visibleToEditors(draft, plant.passage),
    );
    const coveredBy = (plant: Plant) =>
      notes.filter((note) => covers(draft, note, plant));
    const missed = testCase.plants.filter((p) => coveredBy(p).length === 0);
    const expectedHit = testCase.plants.filter((plant) =>
      coveredBy(plant).some((note) =>
        plant.expectedEditors.includes(note.personaId),
      ),
    );
    const primary = notes.map((note) => note.anchor).filter(Boolean) as string[];

    const scores: Record<string, Score> = {
      notes_complete: {
        score: ratio(written.length, 5),
        explanation:
          `${written.length} of 5 editors wrote a note` +
          (withheldOf(raw).length
            ? `; withheld by the editorial review: ${withheldOf(raw).join(", ")}`
            : ""),
      },
      hosted: {
        score:
          ratio(
            notes.filter((note) => note.provider && note.provider !== "local").length,
            notes.length,
          ) ?? 0,
        explanation: `providers: ${[...new Set(notes.map((n) => n.provider))].join(", ")}`,
      },
      anchored: {
        score: ratio(notes.filter((note) => note.anchor).length, notes.length) ?? 0,
        explanation: "share of notes pinned to a passage by quote_passage",
      },
      anchor_verbatim: {
        // No anchors at all is a room that pinned nothing, not a missing check.
        score: ratio(verbatim.length, anchors.length) ?? 0,
        explanation: `${verbatim.length}/${anchors.length} anchors appear verbatim in the draft`,
      },
      plant_coverage: {
        score: ratio(testCase.plants.length - missed.length, testCase.plants.length),
        explanation: missed.length
          ? `missed: ${missed.map((p) => `${p.id} (${p.kind})`).join(", ")}`
          : "every planted feature was noticed",
      },
      plant_coverage_visible: {
        score:
          ratio(
            visible.filter((plant) => coveredBy(plant).length > 0).length,
            visible.length,
          ) ?? 1,
        explanation: `${testCase.plants.length - visible.length} plant(s) sit in the middle the editors' 4,500-character clamp drops`,
      },
      expected_editor: {
        score: ratio(expectedHit.length, testCase.plants.length),
        explanation: "planted features noticed by an editor whose remit covers them",
      },
      anchor_spread: {
        score: ratio(new Set(primary.map(fold)).size, primary.length) ?? 0,
        explanation: "distinct passages chosen across the room",
      },
      voice_distinctness: {
        score: distinctness(written.map((note) => note.text)) ?? 0,
        explanation: "1 minus mean pairwise trigram overlap between notes",
      },
    };

    if (judge) {
      const verdicts = await Promise.all(
        written.map(async (note) => ({
          note,
          faithful: await judgeFaithfulness(judge, draft, note.text),
          helpful: await judgeHelpfulness(
            judge,
            `${note.personaName ?? note.personaId} (${note.personaId})`,
            draft,
            note.text,
          ),
          value: await judgeNoteValue(judge, {
            draft,
            persona: `${note.personaName ?? note.personaId} (${note.personaId})`,
            note: note.text,
            anchor: note.anchor,
          }),
        })),
      ).then(
        (value) => ({ ok: true as const, value }),
        (error: unknown) => ({ ok: false as const, error }),
      );
      const perNote = (pick: "faithful" | "helpful" | "value"): Score =>
        verdicts.ok
          ? {
              score: mean(verdicts.value.map((v) => v[pick].score)) ?? 0,
              explanation:
                verdicts.value
                  .map((v) => `${v.note.personaId}: ${v[pick].label}`)
                  .join("; ") || "no notes to judge",
            }
          : {
              score: null,
              label: "judge-error",
              explanation:
                verdicts.error instanceof Error
                  ? verdicts.error.message
                  : String(verdicts.error),
            };
      scores.faithfulness = await judged(async () => perNote("faithful"));
      scores.helpfulness = await judged(async () => perNote("helpful"));
      // The discriminating one: anchored 1-5 levels, scaled to 0-1.
      scores.note_value = await judged(async () => perNote("value"));
    }
    if (jev && written.length) {
      // One batched Jev request per note, all notes in parallel.
      const perNote = await Promise.all(
        written.map((note) =>
          askJev(
            jev,
            { draft, note: note.text, anchor: note.anchor ?? "(no passage quoted)" },
            JEV_NOTE_QUESTIONS,
          ),
        ),
      );
      for (const key of Object.keys(JEV_NOTE_QUESTIONS)) {
        const values = perNote.map((answers) => answers[key]?.score ?? null);
        const failed = perNote.filter((answers) => answers[key]?.label === "jev-error").length;
        scores[key] = {
          score: failed === perNote.length ? null : mean(values),
          label: failed === perNote.length ? "jev-error" : undefined,
          explanation: written
            .map((note, i) => `${note.personaId}: ${perNote[i][key]?.label ?? "?"}`)
            .join("; "),
        };
      }
    }
    return scores;
  },

  example: (testCase) => ({
    case_id: testCase.case_id,
    genre: testCase.genre,
    draftText: testCase.draftText,
    brief: JSON.stringify(testCase.brief),
    plants: JSON.stringify(testCase.plants),
  }),
};
